#include <algorithm>
#include <array>
#include <cstddef>
#include <cstdint>
namespace { constexpr std::size_t QN=128; std::uint32_t next_rng(std::uint32_t&s){auto x=s;x^=x<<13;x^=x>>17;x^=x<<5;s=x?x:0x9e3779b9U;return s;} std::size_t part(std::int64_t*a,std::size_t lo,std::size_t hi){auto pivot=a[hi];auto i=lo;for(auto j=lo;j<hi;j++)if(a[j]<=pivot)std::swap(a[i++],a[j]);std::swap(a[i],a[hi]);return i;} std::int64_t select_k(std::int64_t*a,std::size_t lo,std::size_t hi,std::size_t k,std::uint32_t&s){if(lo==hi)return a[lo];auto p=lo+next_rng(s)%static_cast<std::uint32_t>(hi-lo+1);std::swap(a[p],a[hi]);p=part(a,lo,hi);auto rank=p-lo+1;if(k==rank)return a[p];if(k<rank)return select_k(a,lo,p-1,k,s);return select_k(a,p+1,hi,k-rank,s);} }
extern "C" std::int64_t minimum_element_of_array(const std::int64_t*input,std::size_t length) noexcept {if(!input||length<4)return -1;auto n0=input[0],k0=input[1],seed0=input[2];if(n0<1||n0>QN||length!=static_cast<std::size_t>(n0)+3||k0<1||k0>n0||seed0<0||seed0>2147483647)return -1;std::array<std::int64_t,QN>a{};for(std::size_t i=0;i<static_cast<std::size_t>(n0);i++){a[i]=input[i+3];if(a[i]<-1000000||a[i]>1000000)return -1;for(std::size_t j=0;j<i;j++)if(a[i]==a[j])return -1;}auto state=static_cast<std::uint32_t>(seed0);if(!state)state=0x9e3779b9U;return select_k(a.data(),0,static_cast<std::size_t>(n0)-1,static_cast<std::size_t>(k0),state);}
